    ["Source", `${S.imported.file} (${S.imported.source})`],
    ["Rooms read", `${S.imported.rooms_kept} of ${S.imported.rooms_read} outlines`],
    ["Plot", `${(+b.plot_width).toFixed(1)} × ${(+b.plot_depth).toFixed(1)} m`],

