878:.revise__k { grid-column: 1 / -1; font-size: 10px; font-weight: 600; letter-spacing: 0.16em; text-transform: uppercase; color: var(--cream-3); }
879:.revise__in { min-width: 0; height: 34px; padding: 0 10px; background: transparent; border: 1px solid var(--rule-2); color: var(--cream); font: 500 12px var(--ui); }
880:.revise__in:focus { outline: none; border-color: var(--cream-3); }
881:.revise .ghost-btn { height: 34px; padding: 0 12px; font-size: 11px; }
882:.revise__said { grid-column: 1 / -1; margin: 0; min-height: 1em; font-size: 11px; color: var(--cream-3); }
1161:.revise__ideas { grid-column: 1 / -1; display: flex; flex-wrap: wrap; gap: 6px; }
1162:.revise__idea { padding: 5px 10px; border: 1px solid var(--rule-2); border-radius: 999px; background: none; color: var(--cream-2); font: 500 11.5px var(--ui); cursor: pointer; transition: border-color .15s, color .15s, background .15s; }
1163:.revise__idea:hover { border-color: var(--cream-3); color: var(--cream); background: rgba(var(--c-rgb), 0.05); }
