/* ── fast-forward ─────────────────────────────────────────────────── */
.at-ff { position: absolute; right: var(--gut); bottom: 28px; z-index: 5; display: flex; align-items: center; gap: 10px; height: 52px; padding: 0 18px 0 8px; border: 1px solid var(--rule-2); border-radius: 999px; background: rgba(11, 10, 9, 0.82); color: var(--cream); cursor: pointer; backdrop-filter: blur(6px); animation: ff-in .5s var(--ease) both; transition: transform .25s var(--ease), border-color .25s var(--ease); }
.at-ff:hover { transform: translateY(-2px); border-color: var(--cream-3); }
.at-ff svg { position: relative; width: 36px; height: 36px; padding: 8px; fill: var(--cream); }
.at-ff__ring { position: absolute; left: 8px; top: 8px; width: 36px; height: 36px; border-radius: 50%; border: 1px solid var(--cream-3); animation: ff-ring 1.8s var(--ease) infinite; }
.at-ff__a, .at-ff__b { animation: ff-chev 1.2s var(--ease) infinite; }
.at-ff__b { animation-delay: .15s; }
.at-ff__k { font-size: 11px; font-weight: 600; letter-spacing: 0.16em; text-transform: uppercase; }
.at-ff.is-going svg .at-ff__a, .at-ff.is-going svg .at-ff__b { animation-duration: .35s; }
.at-ff.is-going { border-color: var(--cream); }
@keyframes ff-in { from { opacity: 0; transform: translateY(12px) scale(.96); } }
@keyframes ff-ring { 0% { transform: scale(.9); opacity: .7; } 70%, 100% { transform: scale(1.5); opacity: 0; } }
@keyframes ff-chev { 0%, 100% { opacity: .35; transform: translateX(0); } 50% { opacity: 1; transform: translateX(2px); } }
@media (prefers-reduced-motion: reduce) { .at-ff, .at-ff * { animation: none !important; } }

/* ═══ HOME: the conversation ═══════════════════════════════════════════ */
.compose { grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr); }
.chat {
  position: relative; height: 100svh; min-width: 0;
  display: grid; grid-template-rows: auto minmax(0, 1fr) auto; gap: 14px;
  padding: calc(var(--bar-h) + clamp(20px, 4vh, 48px)) var(--gut) 28px;
}
.chat__head { display: flex; align-items: center; gap: 6px; border-bottom: 1px solid var(--rule); padding-bottom: 12px; }
.chat__k { margin-right: auto; font-size: 11px; font-weight: 600; letter-spacing: 0.16em; text-transform: uppercase; color: var(--cream-3); }
.chat__manual { padding: 6px 10px; border: 1px solid var(--rule); border-radius: 999px; background: none; color: var(--cream-3); font: 600 11px/1 var(--ui); cursor: pointer; transition: color .2s var(--ease), border-color .2s var(--ease); }
.chat__manual:hover { color: var(--cream); border-color: var(--rule-2); }
.chat__log { overflow-y: auto; display: flex; flex-direction: column; gap: 14px; padding: 4px 2px 8px; scroll-behavior: smooth; overscroll-behavior: contain; }
.msg { max-width: 88%; animation: msg-in .35s var(--ease) both; }
.msg--you { align-self: flex-end; padding: 10px 14px; border-radius: 16px 16px 4px 16px; background: rgba(var(--c-rgb), 0.09); }
.msg--studio { align-self: flex-start; }
.msg__who { display: inline-flex; align-items: center; gap: 6px; margin-bottom: 4px; font-size: 10px; font-weight: 700; letter-spacing: 0.16em; text-transform: uppercase; color: var(--ochre); }
.msg__who::before { content: ""; width: 14px; height: 14px; background: url("logo-arch.svg") center / contain no-repeat; }
.msg__body { margin: 0; font-size: 15px; line-height: 1.55; color: var(--cream); white-space: pre-wrap; }
.msg--you .msg__body { font-size: 14px; color: var(--cream-2); }

