  ["dining", "Dining"], ["living", "Living"], ["store", "Store"], ["utility", "Utility"], ["puja", "Puja"],
  ["guest_bedroom", "Guest bedroom"], ["children_bedroom", "Kids' bedroom"], ["laundry", "Laundry"],
];
const STEPS = [0.3, 0.5, 1.0];
const CEILINGS = [2.7, 3.0, 3.3, 3.6, 4.2];

