    .then((r) => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json(); })
    .then((d) => build(d.rooms || []))
    .catch((err) => { body.replaceChildren(el("p", "edit__loading", `The rooms could not be listed (${err.message}).`)); });

